// Large-scale Sri Lanka demo dataset — generates realistic-looking but
// entirely FICTIONAL accounts (models, industry professionals, pageant
// organizers) so the app has real volume to browse/search/filter/paginate
// through, instead of the small ~8-account narrative set in seed-demo.js.
//
// Person names are generated by combining common Sri Lankan given-name and
// surname pools, so no real individual is represented. Pageant and event
// organiser names come from the franchise/fashion-week list in
// pageant-names.js and are used for illustration only.
//
// Run with: node scripts/seed-sri-lanka.js
// Safe to re-run — clears only accounts under the @sl.demo.talent suffix
// first, same idempotency pattern as seed-demo.js. Refuses to run with
// NODE_ENV=production.
require('dotenv').config();
const mongoose = require('mongoose');
const User = require('../models/User');
const ModelProfile = require('../models/ModelProfile');
const IndustryProfile = require('../models/IndustryProfile');
const PageantOrgProfile = require('../models/PageantOrgProfile');
const PAGEANT_NAMES = require('./pageant-names');
const { ensureAcceptedChat } = require('./chat-demo');
const PortfolioItem = require('../models/PortfolioItem');
const CastingCall = require('../models/CastingCall');
const Application = require('../models/Application');

if (process.env.NODE_ENV === 'production') {
  console.error(
    'Refusing to run seed-sri-lanka.js with NODE_ENV=production. This script is for local/dev use only.',
  );
  process.exit(1);
}

const COUNT_PER_ROLE = parseInt(process.argv[2], 10) || 100;
const EMAIL_SUFFIX = '@sl.demo.talent';
const PASSWORD = 'Password123';

const { pickPhoto } = require('./sl-photos');
const img = (isFemale, seed, width) => pickPhoto(isFemale, seed, width);

// ---------------------------------------------------------------------------
// Name pools (fictional combinatorics, not real individuals)
// ---------------------------------------------------------------------------
